/* Island Pin Beats: offline app cache (generated by beats/tools/gen-sw.py — edit tools/sw-template.js, then regenerate).
 * After the first visit Beats, Studio, Master, the Sound check and every kit sound work with no connection.
 * HTML: network first (3 s), cached copy when offline. Versioned files (?v=): cache first. Library sounds keep their own
 * cache (library.js, "Download all sounds"). Scope: /beats/ only (Player / DJ keep their own). */
var VERSION = "__VERSION__", CACHE = "ipb-app-" + VERSION, BASE = self.registration.scope; // …/beats/
var CORE = __CORE__, EXTRA = __EXTRA__, SHARED = __SHARED__;
function abs(p) { return p.charAt(0) === "/" ? new URL(p, BASE).href : new URL(p, BASE).href; }
self.addEventListener("install", function (e) {
  e.waitUntil(caches.open(CACHE).then(function (c) {
    // core code first (≈1.4 MB); a missing file must not break the install
    return Promise.all(CORE.concat(SHARED).map(function (p) { return c.add(new Request(abs(p), { cache: "reload" })).catch(function () { /* skip */ }); }));
  }).then(function () { return self.skipWaiting(); }));
});
self.addEventListener("activate", function (e) {
  e.waitUntil(caches.keys().then(function (ks) {
    return Promise.all(ks.filter(function (k) { return /^ipb-app-/.test(k) && k !== CACHE; }).map(function (k) { return caches.delete(k); }));
  }).then(function () { return self.clients.claim(); }).then(function () { fillExtra(); }));
});
/* kit sounds + noise-reduction model (≈7 MB) after activation, one at a time so the app stays responsive */
function fillExtra() {
  return caches.open(CACHE).then(function (c) {
    var i = 0;
    function next() {
      if (i >= EXTRA.length) return Promise.resolve();
      var u = abs(EXTRA[i++]);
      return c.match(u).then(function (hit) { return hit || fetch(u).then(function (r) { if (r.ok) return c.put(u, r); }); }).catch(function () { /* offline: later */ }).then(next);
    }
    return next();
  });
}
function inScope(u) { return u.origin === self.location.origin && (u.pathname.indexOf(new URL(BASE).pathname) === 0 || /^\/shared\//.test(u.pathname)); }
function fromCache(req) {
  return caches.open(CACHE).then(function (c) { return c.match(req).then(function (r) { return r || c.match(req, { ignoreSearch: true }); }); });
}
self.addEventListener("fetch", function (e) {
  var req = e.request; if (req.method !== "GET") return;
  var u = new URL(req.url); if (!inScope(u)) return;
  if (/\/library\//.test(u.pathname) && !/manifest\.json$/.test(u.pathname)) return; // library.js caches sounds itself
  if (/[?&](build|fresh)=/.test(u.search) || req.cache === "no-store") return; // stale-build check / Start fresh: always the network
  if (req.mode === "navigate") {
    e.respondWith(new Promise(function (res) {
      var done = false, to = setTimeout(function () { fromCache(req).then(function (r) { if (r && !done) { done = true; res(r); } }); }, 3000);
      fetch(req).then(function (r) {
        if (r.ok) { var cp = r.clone(); caches.open(CACHE).then(function (c) { c.put(u.origin + u.pathname, cp); }); }
        if (!done) { done = true; clearTimeout(to); res(r); }
      }).catch(function () {
        fromCache(new Request(u.origin + u.pathname)).then(function (r) { if (!done) { done = true; clearTimeout(to); res(r || caches.match(abs("./"), { ignoreSearch: true }).then(function (x) { return x || new Response("Offline: open Beats once with a connection first.", { status: 503, headers: { "Content-Type": "text/plain" } }); })); } });
      });
    }));
    return;
  }
  var versioned = /[?&]v=/.test(u.search) || /\.(flac|mp3|wav|wasm|png|svg)$/.test(u.pathname);
  e.respondWith(caches.open(CACHE).then(function (c) {
    return c.match(req).then(function (hit) {
      var net = fetch(req).then(function (r) { if (r.ok && r.type === "basic") c.put(req, r.clone()); return r; });
      if (hit && versioned) return hit;                       // cache first for versioned files
      if (hit) { net.catch(function () {}); return hit; }     // stale-while-revalidate for the rest
      return net.catch(function () { return c.match(req, { ignoreSearch: true }).then(function (r) { return r || Response.error(); }); });
    });
  }));
});
self.addEventListener("message", function (e) { if (e.data === "extra") e.waitUntil(fillExtra()); });
